// Writes the film-look LUTs bundled with zvid to public/luts/, one `.cube`
// file per entry of BUILTIN_LUTS in src/fx/effects/lut/builtin-luts.ts, plus
// the CREDITS.md that lists them. Each look is a documented color transform
// in LOOKS below, sampled on a LUT_SIZE³ grid, so every file is generated by
// zvid and carries no third-party license. The output is committed; the unit
// tests fail when a committed file no longer matches its transform.
//
//   node scripts/gen-film-luts.mjs          regenerate the LUTs
//   node scripts/gen-film-luts.mjs --check  exit 1 if a LUT is stale

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { BUILTIN_LUTS } from "../src/fx/effects/lut/builtin-luts.ts";

const APP_DIR = join(dirname(fileURLToPath(import.meta.url)), "..");
export const LUTS_DIR = join(APP_DIR, "public", "luts");
export const CREDITS_PATH = join(LUTS_DIR, "CREDITS.md");

// 17³ samples is a common LUT size: these looks are smooth curves that the
// LUT effect's trilinear lookup reproduces closely, and each file stays
// near 130 KB.
export const LUT_SIZE = 17;

const clamp01 = (value) => Math.min(1, Math.max(0, value));
const mix = (a, b, t) => a + (b - a) * t;
const mixRgb = (a, b, t) => a.map((value, index) => mix(value, b[index], t));
const smoothstep = (edge0, edge1, x) => {
  const t = clamp01((x - edge0) / (edge1 - edge0));
  return t * t * (3 - 2 * t);
};
// Rec. 709 luma.
const luma = ([r, g, b]) => 0.2126 * r + 0.7152 * g + 0.0722 * b;
const saturate = (rgb, amount) => {
  const y = luma(rgb);
  return rgb.map((value) => mix(y, value, amount));
};
// S-shaped contrast curve around `pivot`: 0 leaves `x` unchanged.
const sCurve = (x, amount, pivot = 0.5) => {
  const curved =
    x < pivot
      ? pivot * (x / pivot) ** (1 + amount)
      : 1 - (1 - pivot) * ((1 - x) / (1 - pivot)) ** (1 + amount);
  return clamp01(curved);
};
// Maps 0..1 onto `black`..`white`, so a raised black fades shadows and a
// lowered white softens highlights the way a print does.
const range = (x, black, white) => black + (white - black) * x;

/** Each look's transform, keyed by BUILTIN_LUTS id. Inputs and outputs are
 * display-referred RGB in 0..1. */
export const LOOKS = {
  // Panchromatic black-and-white stock with a light yellow filter: reds and
  // greens read brighter than blues, then a film S-curve.
  "builtin:bw-film": (rgb) => {
    const [r, g, b] = rgb;
    const y = sCurve(0.32 * r + 0.58 * g + 0.1 * b, 0.45);
    return [y, y, y];
  },
  // Monochrome toned from deep brown shadows to cream highlights.
  "builtin:sepia": (rgb) => {
    const y = sCurve(luma(rgb), 0.2);
    return mixRgb([0.13, 0.08, 0.04], [1, 0.93, 0.78], y);
  },
  // An aged print: milky blacks, dimmed whites, faded color, cyan-tinted
  // shadows and warm highlights.
  "builtin:faded-vintage": (rgb) => {
    const faded = saturate(rgb, 0.6).map((value) => range(value, 0.1, 0.9));
    const t = smoothstep(0.1, 0.9, luma(faded));
    const tint = mixRgb([-0.02, 0.02, 0.04], [0.04, 0.01, -0.04], t);
    return faded.map((value, index) => value + tint[index]);
  },
  // Golden 1970s color: warm balance, slightly muted saturation, soft
  // contrast and amber-lifted blacks.
  "builtin:warm-70s": (rgb) => {
    const [r, g, b] = saturate(rgb, 0.85);
    const warm = [r * 1.08 + 0.03, g * 1.0 + 0.015, b * 0.82];
    return warm.map((value) => range(sCurve(clamp01(value), 0.15), 0.03, 0.97));
  },
  // Cool 1980s/90s color: blue-green shadows, crisp contrast and a slight
  // pull out of the reds.
  "builtin:cool-90s": (rgb) => {
    const [r, g, b] = saturate(rgb, 0.9);
    const cool = [r * 0.92, g * 1.0 + 0.01, b * 1.08 + 0.02];
    const t = smoothstep(0, 0.6, luma(cool));
    const shadowTint = [-0.03, 0.02, 0.04].map((value) => value * (1 - t));
    return cool.map((value, index) =>
      sCurve(clamp01(value + shadowTint[index]), 0.3),
    );
  },
  // Skipping the bleach bath leaves silver in the print: a black-and-white
  // overlay that drains color and hardens contrast.
  "builtin:bleach-bypass": (rgb) => {
    const y = luma(rgb);
    const silver = sCurve(y, 0.8);
    return saturate(rgb, 0.4).map((value) => {
      // Overlay blend of the color image with its contrasty silver layer.
      const overlay =
        value < 0.5 ? 2 * value * silver : 1 - 2 * (1 - value) * (1 - silver);
      return mix(value, overlay, 0.7);
    });
  },
  // Slide film developed as negative: per-channel curves give yellow-green
  // highlights, blue shadows and punchy saturation.
  "builtin:cross-processed": (rgb) => {
    const [r, g, b] = saturate(rgb, 1.15);
    return [
      sCurve(clamp01(r), 0.6),
      clamp01(g) ** 0.88,
      range(clamp01(b) ** 1.15, 0.12, 0.82),
    ];
  },
  // Early two-color process: a red-orange record and a cyan-green record,
  // so blues and greens collapse into teal and reds stay warm.
  "builtin:two-strip": (rgb) => {
    const [r, g, b] = rgb;
    const red = r;
    const cyan = 0.65 * g + 0.35 * b;
    return [
      sCurve(red * 0.95 + cyan * 0.05, 0.2),
      sCurve(red * 0.2 + cyan * 0.8, 0.2),
      sCurve(cyan * 0.85, 0.2),
    ];
  },
  // Hard print stock: crushed blacks, bright whites and a little extra
  // saturation.
  "builtin:high-contrast": (rgb) =>
    saturate(rgb, 1.1).map((value) =>
      sCurve(clamp01(range(value, -0.03, 1.02)), 0.9),
    ),
  // Modern blockbuster split-tone: teal shadows and orange highlights and
  // skin, with a slight saturation boost.
  "builtin:teal-orange": (rgb) => {
    const t = smoothstep(0.15, 0.85, luma(rgb));
    const tint = mixRgb([-0.07, 0.02, 0.08], [0.08, 0.02, -0.08], t);
    return saturate(rgb, 1.1).map((value, index) =>
      sCurve(clamp01(value + tint[index]), 0.15),
    );
  },
};

function formatValue(value) {
  if (!Number.isFinite(value)) throw new Error(`Non-finite LUT value ${value}`);
  return clamp01(value).toFixed(6);
}

/** Renders `look` as a `.cube` file with red varying fastest, as the format
 * requires. */
export function renderCube(lut, look, size = LUT_SIZE) {
  const lines = [
    `TITLE "${lut.name}"`,
    `# ${lut.name}, a film look generated by zvid's`,
    "# app/scripts/gen-film-luts.mjs. Do not edit; run",
    "# `node app/scripts/gen-film-luts.mjs` after changing a look.",
    `LUT_3D_SIZE ${size}`,
    "DOMAIN_MIN 0.0 0.0 0.0",
    "DOMAIN_MAX 1.0 1.0 1.0",
  ];
  for (let b = 0; b < size; b += 1) {
    for (let g = 0; g < size; g += 1) {
      for (let r = 0; r < size; r += 1) {
        const input = [r, g, b].map((index) => index / (size - 1));
        lines.push(look(input).map(formatValue).join(" "));
      }
    }
  }
  return `${lines.join("\n")}\n`;
}

export function renderCredits(luts = BUILTIN_LUTS) {
  const rows = luts.map(
    (lut) =>
      `| \`${lut.file}\` | ${lut.name} | \`${lut.id}\` | Generated by zvid | zvid | Same as zvid | — |`,
  );
  return `# zvid built-in LUTs: credits

These are the film-look LUTs listed under "Built-in" in the LUT effect's
picker. Keep this file with them when you redistribute them.

Every LUT here is generated by zvid: \`app/scripts/gen-film-luts.mjs\`
samples a documented color transform for each look on a ${LUT_SIZE}×${LUT_SIZE}×${LUT_SIZE}
grid. None is taken from a third-party pack, so none carries a third-party
license; they are distributed under zvid's own license. Look names describe
the look and are not film-stock trademarks.

| File | Look | Id | Source | Author | License | License URL |
| --- | --- | --- | --- | --- | --- | --- |
${rows.join("\n")}
`;
}

/** Every file the generator owns, as `[path, contents]`. */
export function renderAll() {
  const files = BUILTIN_LUTS.map((lut) => {
    const look = LOOKS[lut.id];
    if (!look) throw new Error(`No look transform for ${lut.id}`);
    return [join(LUTS_DIR, lut.file), renderCube(lut, look)];
  });
  files.push([CREDITS_PATH, renderCredits()]);
  return files;
}

function readOrEmpty(file) {
  try {
    return readFileSync(file, "utf8").replace(/\r\n/g, "\n");
  } catch {
    return "";
  }
}

function main() {
  const check = process.argv.includes("--check");
  const stale = [];
  mkdirSync(LUTS_DIR, { recursive: true });
  for (const [file, expected] of renderAll()) {
    if (readOrEmpty(file) === expected) continue;
    if (check) stale.push(file);
    else writeFileSync(file, expected);
  }
  if (stale.length > 0) {
    console.error(
      `Stale built-in LUTs; run node app/scripts/gen-film-luts.mjs:\n${stale.join("\n")}`,
    );
    process.exit(1);
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
